  function psalterWeek(L, date) {
    const y = date.getUTCFullYear(), t = Math.floor(date.getTime() / DAY), dow = date.getUTCDay();
    const E = Math.floor(L.westernEaster(y).getTime() / DAY), adv = yd(y, 12, 25) - (new Date(Date.UTC(y, 11, 25)).getUTCDay() || 7) - 21, xmas = yd(y, 12, 25);
    const w = n => ((n - 1) % 4 + 4) % 4 + 1;
    if (t >= adv) return t < xmas ? w(Math.floor((t - adv) / 7) + 1) : w(Math.floor((t - xmas) / 7) + 1);
    const epi = yd(y, 1, 2) + ((7 - new Date(Date.UTC(y, 0, 2)).getUTCDay()) % 7), bap = epi >= yd(y, 1, 7) ? epi + 1 : epi + 7;
    if (t < bap + 1) return w(Math.floor((t - yd(y - 1, 12, 25)) / 7) + 1);
    if (t < E - 46) { const s2 = bap + 1 + ((7 - ((bap + 1 + 4) % 7)) % 7); return t < s2 ? 1 : w(2 + Math.floor((t - s2) / 7)); }
    if (t < E - 42) return 4;
    if (t < E) return w(Math.floor((t - (E - 42)) / 7) + 1);
    if (t <= E + 49) return w(Math.floor((t - E) / 7) + 1);
    const sun = t - dow; return w(35 - (adv - sun) / 7);
  }
  function canticleBlock(label, refs) {
    return `<div class="psalm"><div class="muted" style="font-size:.78rem">${esc(label)}</div><div class="asv" data-ref="${esc(refs)}" data-tr="dra"></div><div class="muted" style="margin-top:6px">${esc(H.g.Gloria).replace(/\n/g, '<br>')}</div></div>`;
  }
  function modern(L, date, which) {
    let d = date, first = false;
    if (which === 'V' && date.getUTCDay() === 6) { d = L.add(date, 1); first = true; }
    const dow = d.getUTCDay(), pw = psalterWeek(L, d);
    let items;
    if (which === 'L') items = MP[pw][dow];
    else items = dow === 0 ? (first ? EP1[pw] : SUN_V[pw]) : EP[pw][dow];
    const trad = hour(L, date, which), wk = week(L, d), tmp = H.temp[`${wk}-${dow}`] || {}, sun = H.temp[`${wk}-0`] || {}, D = H.days[dow][which];
    const hymn = seasonHymn(wk, which) || D.hymn, coll = tmp.O || sun.O || '';
    const name = which === 'L' ? 'Morning Prayer (Lauds)' : 'Evening Prayer (Vespers)';
    let h = `<p class="muted" style="font-size:.82rem">${first ? 'Evening Prayer I of Sunday. ' : ''}${name} · modern four-week psalter, Week ${['', 'I', 'II', 'III', 'IV'][pw]}. Psalms in the Douay translation (Vulgate numbers). Each psalm’s antiphon is its own opening verse. The short reading and responsory are the traditional ones. The current books’ antiphons, readings and intercessions are copyrighted and are not included.</p>`;
    h += `<div class="sec"><b>Opening</b>${lines(H.g['Deus in adjutorium'])}</div>`;
    if (hymn) h += `<div class="sec"><b>Hymn (traditional)</b>${lines(hymn)}</div>`;
    h += '<div class="sec"><b>Psalmody</b>' + items.map(it => {
      if (it[0] === 'p') { const pp = psalm(it.slice(1))[0], ant = pp && pp.rows[0] ? vclean(pp.rows[0][2]).replace(/\s*\*\s*/g, ' ') : ''; return (ant ? `<div class="ant"><i>Ant.</i> ${esc(ant)}</div>` : '') + psalmHTML(it.slice(1)); }
      if (it[0] === 'c') return canticle(it.slice(1));
      const [, rest] = it.split(/^b:/), [label, ...refs] = rest.split('|'); return canticleBlock(label, refs.join('|'));
    }).join('') + '</div>';
    const cap = (which === 'L' ? tmp.C || (dow === 0 ? sun.C : '') : '') || D.cap;
    if (cap) h += `<div class="sec"><b>Short reading (traditional chapter)</b>${lines(cap)}</div>`;
    if (D.resp) h += `<div class="sec"><b>Short responsory (traditional)</b>${lines(D.resp)}</div>`;
    h += `<div class="sec"><b>${which === 'L' ? 'Benedictus' : 'Magnificat'}</b>${canticle(which === 'L' ? '231' : '232')}</div>`;
    h += `<div class="sec"><b>Our Father</b><div>Our Father, who art in heaven, hallowed be thy name; thy kingdom come; thy will be done on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses as we forgive those who trespass against us; and lead us not into temptation, but deliver us from evil. Amen.</div></div>`;
    if (coll) h += `<div class="sec"><b>Collect (traditional)</b>${lines('Let us pray.')}${lines(coll)}</div>`;
    h += `<div class="sec"><b>Conclusion</b>${lines(H.g.Dominus.split('\n').slice(0, 2).join('\n'))}<br>${lines(H.g['Benedicamus Domino'])}</div>`;
    return h;
  }

